import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Table Advance Options","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/table-advance-options.md","filePath":"documentation/field-types/table-advance-options.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/table-advance-options.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="table-advance-options" tabindex="-1">Table Advance Options <a class="header-anchor" href="#table-advance-options" aria-label="Permalink to “Table Advance Options”">​</a></h1><p>When using this field type, the following buttons will be inserted at the top of the table.</p><img src="/image/table-advance-options-01.png" alt="Image"><ul><li><strong>Export to Excel</strong>: Exports the table data into an Excel (<code>.xlsx</code>) sheet.</li><li><strong>Export All Table to Excel</strong>: Exports all tables on the page into a single Excel (<code>.xlsx</code>) workbook with individual sheets.</li><li><strong>Print Table</strong>: Opens a print window to print the table data directly from the page.</li></ul><hr><h2 id="field-element-selector-options" tabindex="-1">Field Element Selector Options <a class="header-anchor" href="#field-element-selector-options" aria-label="Permalink to “Field Element Selector Options”">​</a></h2><p>These options allow users to specify the type and query for selecting element.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td>Selector Type</td><td>Specifies the type of selector being used. Available types may include Selector or other types, depending on the context.</td><td><code>Selector</code>, <code>#ID</code>, <code>XPath</code></td></tr><tr><td>Selector Query</td><td>Defines the <code>query</code> or <code>CSS</code> selector to target the specific element.</td><td></td></tr></tbody></table><h2 id="element-query-behavior" tabindex="-1">Element Query Behavior <a class="header-anchor" href="#element-query-behavior" aria-label="Permalink to “Element Query Behavior”">​</a></h2><p>If you don&#39;t specify an element query, the field action will apply to <strong>all tables</strong> on the page.</p><p>This means that any actions associated with this field, like exporting or printing, will be performed on all tables.</p><p>If you want to target a specific table, you&#39;ll need to provide an element query. This query will define which table (or tables) the action should be applied to.</p><p>For more information on how to find the correct element query, please refer to the documentation on <a href="/documentation/locate-element.html">How to Find Element Selector Query</a>.</p><hr><h2 id="table-data-prepare-clean-options" tabindex="-1">Table Data Prepare &amp; Clean Options <a class="header-anchor" href="#table-data-prepare-clean-options" aria-label="Permalink to “Table Data Prepare &amp; Clean Options”">​</a></h2><p>The <strong>Table Data Prepare &amp; Clean</strong> settings provide controls to sanitize, format, and extract interactive elements from table cells prior to exporting or printing.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Prepare and clean table cell contents before export/print?</strong></td><td><strong>Master Switch</strong>. When enabled, activates advanced cleaning and extraction for all elements inside table cells.</td></tr><tr><td><strong>Image Content Mode in Table</strong></td><td>Controls how images within table cells are handled during export or print.</td></tr><tr><td><strong>Include button text in exported table?</strong></td><td>Choose whether to include or exclude text labels from <code>&lt;button&gt;</code> elements.</td></tr><tr><td><strong>Include anchor link text/URL?</strong></td><td>Choose whether to extract anchor text and link URLs (<code>&lt;a&gt;</code> tags).</td></tr><tr><td><strong>Extract current values of input fields (text, number, date)?</strong></td><td>Extracts live user-entered values from text, numeric, date, and other <code>&lt;input&gt;</code> fields instead of blank inputs.</td></tr><tr><td><strong>Extract selected radio &amp; checkbox labels (omit unselected)?</strong></td><td>Extracts only the labels of checked/selected radio buttons and checkboxes, omitting unselected choices.</td></tr><tr><td><strong>Extract selected dropdown/select option text?</strong></td><td>Extracts the visible label text of the chosen option from <code>&lt;select&gt;</code> dropdown menus.</td></tr><tr><td><strong>Extract textarea content values?</strong></td><td>Extracts user-entered multiline text values from <code>&lt;textarea&gt;</code> elements.</td></tr><tr><td><strong>Format and include nested sub-tables?</strong></td><td>Formats and cleanly includes nested child tables within parent table cells.</td></tr></tbody></table><h3 id="image-content-mode-in-table" tabindex="-1">Image Content Mode in Table <a class="header-anchor" href="#image-content-mode-in-table" aria-label="Permalink to “Image Content Mode in Table”">​</a></h3><p>When cleaning table content, you can choose how images are extracted using the <strong>Image Content Mode in Table</strong> dropdown:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>Extract Image URL (Link)</strong></td><td>Replaces the image element with its direct source URL link (<code>src</code>).</td></tr><tr><td><strong>Extract Image Alt Text / Title Description</strong></td><td>Extracts the image&#39;s descriptive text from its <code>alt</code> or <code>title</code> attributes.</td></tr><tr><td><strong>Preserve Visual Image Element (<code>&lt;img&gt;</code> tag)</strong></td><td>Retains the actual visual image element in the table.</td></tr><tr><td><strong>Skip Images (None)</strong></td><td>Completely ignores and strips images from the exported or printed output.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Auto Restore</p><p>Immediately after the export or print action completes, Excellent Data Filler automatically reverts the table back to its original interactive state. Live input values, interactive elements, and web page layout remain intact without requiring a page refresh.</p></div><hr><h2 id="export-excel-options" tabindex="-1">Export Excel Options <a class="header-anchor" href="#export-excel-options" aria-label="Permalink to “Export Excel Options”">​</a></h2><p>Configure export settings when downloading table data as an Excel (<code>.xlsx</code>) spreadsheet.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Visible all rows in excel sheet?</strong></td><td>If enabled, all visible rows in the table will be exported to the Excel sheet. If disabled, only rows currently displayed on the screen will be exported.</td></tr><tr><td><strong>Do you want to skip any sheets having sheet while downloading all table data?</strong></td><td>If enabled, specify a list of sheet names to exclude from the export process.</td></tr><tr><td><strong>Do you want to include any sheets having sheet while downloading all table data?</strong></td><td>If enabled, specify a list of sheet names to include in the export process, even if they are not currently visible.</td></tr></tbody></table><hr><h2 id="print-options" tabindex="-1">Print Options <a class="header-anchor" href="#print-options" aria-label="Permalink to “Print Options”">​</a></h2><p>Configure settings for printing table data directly from the browser.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Print action automatically trigger when print window is open?</strong></td><td>Automatically triggers the browser&#39;s print dialog as soon as the print preview window opens.</td></tr><tr><td><strong>Do need to set a delay on the print action?</strong></td><td>Specifies a delay (in seconds) before the print action is triggered, allowing styles or dynamic content to fully render.</td></tr><tr><td><strong>Print window automatic close after print done?</strong></td><td>Automatically closes the print window once the print action is completed.</td></tr><tr><td><strong>Do need to set custom url on the print window?</strong></td><td>Specifies a custom URL to be opened in the print window.</td></tr><tr><td><strong>Would you to add custom styles to the print window?</strong></td><td>Specifies custom CSS stylesheets to apply to the print window.</td></tr></tbody></table><h3 id="print-popup-window-options" tabindex="-1">Print Popup Window Options <a class="header-anchor" href="#print-popup-window-options" aria-label="Permalink to “Print Popup Window Options”">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Open print window in pop up window?</strong></td><td>Opens the print preview in a separate popup window instead of a standard tab.</td></tr><tr><td><strong>Do need to set print window height, width and window features?</strong></td><td>Specifies the height, width, and other window features of the popup print window.</td></tr></tbody></table><hr><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use Cases”">​</a></h2><h3 id="export-tables-with-live-user-input" tabindex="-1">Export Tables with Live User Input <a class="header-anchor" href="#export-tables-with-live-user-input" aria-label="Permalink to “Export Tables with Live User Input”">​</a></h3><p><strong>Scenario:</strong> A web portal table includes interactive inputs such as editable text boxes, date pickers, dropdown selects, and checkboxes that users have filled in.</p><p><strong>Configuration:</strong></p><ul><li>Enable <strong>Prepare and clean table cell contents before export/print?</strong></li><li>Enable <strong>Extract current values of input fields (text, number, date)?</strong></li><li>Enable <strong>Extract selected radio &amp; checkbox labels (omit unselected)?</strong></li><li>Enable <strong>Extract selected dropdown/select option text?</strong></li></ul><p><strong>Result:</strong> The exported Excel (<code>.xlsx</code>) sheet contains the actual values entered by the user rather than empty input elements. Once exported, the page table is automatically restored to its interactive state.</p><hr><h3 id="export-product-table-with-image-links" tabindex="-1">Export Product Table with Image Links <a class="header-anchor" href="#export-product-table-with-image-links" aria-label="Permalink to “Export Product Table with Image Links”">​</a></h3><p><strong>Scenario:</strong> An e-commerce table displays product thumbnail images, descriptions, SKU, and &quot;Buy Now&quot; buttons.</p><p><strong>Configuration:</strong></p><ul><li>Set <strong>Image Content Mode in Table</strong> to <strong>Extract Image URL (Link)</strong>.</li><li>Disable <strong>Include button text in exported table?</strong>.</li></ul><p><strong>Result:</strong> The generated Excel file replaces visual thumbnails with direct image URLs and omits button labels, creating a clean catalog dataset.</p><hr><h3 id="clean-print-layout-for-web-invoices-and-reports" tabindex="-1">Clean Print Layout for Web Invoices and Reports <a class="header-anchor" href="#clean-print-layout-for-web-invoices-and-reports" aria-label="Permalink to “Clean Print Layout for Web Invoices and Reports”">​</a></h3><p><strong>Scenario:</strong> Print a web-based data table or invoice directly without page navigation headers, footers, or action buttons.</p><p><strong>Configuration:</strong></p><ul><li>Enable <strong>Open print window in pop up window?</strong>.</li><li>Enable <strong>Print action automatically trigger when print window is open?</strong>.</li><li>Enable <strong>Would you to add custom styles to the print window?</strong> to inject print-specific CSS (e.g., hiding action buttons and adjusting font sizing).</li></ul><p><strong>Result:</strong> A standalone popup window opens with the styled table and immediately opens the browser&#39;s print dialog for fast, clean printing.</p><hr><h3 id="batch-export-all-page-tables-to-excel" tabindex="-1">Batch Export All Page Tables to Excel <a class="header-anchor" href="#batch-export-all-page-tables-to-excel" aria-label="Permalink to “Batch Export All Page Tables to Excel”">​</a></h3><p><strong>Scenario:</strong> An analytical dashboard contains multiple summary tables across different sections of the page.</p><p><strong>Configuration:</strong></p><ul><li>Leave the <strong>Selector Query</strong> empty to apply actions across all page tables.</li><li>Click <strong>Export All Table to Excel</strong>.</li></ul><p><strong>Result:</strong> All tables on the page are consolidated into a single Excel (<code>.xlsx</code>) workbook, with individual tables cleanly separated into dedicated sheets.</p>`,56)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};